    { id: 'alta',    etq: 'Alta',     rango: '15 a 30 %', hasta: 30,      color: '#F59E0B' },
    { id: 'muyalta', etq: 'Muy alta', rango: '> 30 %',   hasta: Infinity, color: '#B91C1C' }
